383:/**
384: * Countries whose right to work the posting explicitly DEMANDS.
385: *
386: * This is the evidence the user asked the gate to require: a remote posting
387: * that merely happens to say "Sweden (Remote)" stays in the queue, and only one
388: * that says, in as many words, that you must live there or be authorised there
389: * is closed. So the country name alone is never enough — it has to sit near a
390: * demand phrase.
391: *
392: * The window is deliberately narrow (a single sentence-ish span) because a long
393: * description mentions many countries for many reasons: offices, customers,
394: * time zones, and the team's own spread.
395: */
396:export function demandedWorkCountries(
397:  text: string | null | undefined,
398:): string[] {
399:  const raw = (text ?? "").toLowerCase();
400:  if (!raw.trim()) return [];
401:  const demands =
402:    /(?:must (?:be |currently )?(?:located|based|reside|live)[^.;\n]{0,40}|must (?:be )?(?:legally )?(?:authori[sz]ed|eligible) to work[^.;\n]{0,40}|(?:legal )?(?:right|authorisation|authorization|permit) to work[^.;\n]{0,40}|work (?:permit|visa|authori[sz]ation)[^.;\n]{0,40}|residen(?:cy|ce) (?:in|required)[^.;\n]{0,40}|no (?:visa )?sponsorship[^.;\n]{0,60}|(?:citizens?|residents?) only[^.;\n]{0,20}|only (?:accepting )?(?:candidates|applicants)[^.;\n]{0,40})/g;
403:  const found: string[] = [];
404:  // A demand phrase followed by its own negation is not a demand. Work at a
405:  // Startup prints "US citizenship/visa not required" on postings that hire
406:  // worldwide, and reading it as a US requirement closed exactly the roles it
407:  // was advertising as open (measured against the scoring fixture,
408:  // 2026-08-18). Narrow on purpose: only an explicit "not required/needed"
409:  // inside the span — "no sponsorship" stays a demand, because it is one.
410:  const negated =
411:    /not?\s+(?:be\s+)?(?:required|necessary|needed)|n[ãa]o\s+(?:[ée]\s+)?(?:exigid|necess[áa]ri)|sem\s+necessidade/;
412:  for (const m of raw.matchAll(demands)) {
413:    const span = m[0];
414:    if (negated.test(span)) continue;
415:    if (namesUnitedStates(span) && !found.includes("United States")) {
416:      found.push("United States");
417:    }
418:    for (const [country, aliases] of Object.entries(COUNTRY_ALIASES)) {
419:      if (found.includes(country)) continue;
420:      if (aliases.some((a) => hasWord(span, a))) found.push(country);
421:    }
422:  }
423:  return found;
424:}

